package me.minis.ledger;
import android.content.*;import android.os.*;import org.json.*;import java.util.concurrent.atomic.AtomicLong;
public final class PowerProbe {
 private static final AtomicLong notifications=new AtomicLong(),screens=new AtomicLong();private static long lastCpu=0,lastElapsed=0,lastBatterySample=0;private static int lastLevel=-1,lastPlug=-1;private static Context app;private static volatile boolean active=false;private static boolean attached=false;
 private static final BroadcastReceiver receiver=new BroadcastReceiver(){public void onReceive(Context c,Intent i){int scale=i.getIntExtra("scale",100),level=i.getIntExtra("level",-1),plug=i.getIntExtra("plugged",0);int percent=scale>0&&level>=0?level*100/scale:-1;long now=SystemClock.elapsedRealtime();if(percent!=lastLevel||plug!=lastPlug||now-lastBatterySample>=60000){lastBatterySample=now;battery(percent,plug);}}};
 public static void init(Context c){app=c.getApplicationContext();lastCpu=android.os.Process.getElapsedCpuTime();lastElapsed=SystemClock.elapsedRealtime();active=LedgerDb.prefs(app).getBoolean("probe_on",false);PowerDetail.init(app);if(active)attach();}
 private static void attach(){if(!attached){attached=true;app.registerReceiver(receiver,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));}}
 private static void detach(){if(attached){attached=false;try{app.unregisterReceiver(receiver);}catch(Exception ignored){}}}
 public static void notification(){if(active)notifications.incrementAndGet();}
 public static void screen(){if(active)screens.incrementAndGet();}
 public static synchronized void sample(){if(app==null)return;PowerDetail.count("probe_sample");SharedPreferences p=LedgerDb.prefs(app);long cpu=android.os.Process.getElapsedCpuTime(),elapsed=SystemClock.elapsedRealtime();long dc=Math.max(0,cpu-lastCpu),dt=Math.max(0,elapsed-lastElapsed);lastCpu=cpu;lastElapsed=elapsed;if(!p.getBoolean("probe_on",false)){notifications.set(0);screens.set(0);return;}
 PowerDetail.sample(dc,dt,lastLevel);
 p.edit().putLong("probe_cpu",p.getLong("probe_cpu",0)+dc).putLong("probe_observed",p.getLong("probe_observed",0)+dt).putLong("probe_notifications",p.getLong("probe_notifications",0)+notifications.getAndSet(0)).putLong("probe_screens",p.getLong("probe_screens",0)+screens.getAndSet(0)).putLong("probe_sample",System.currentTimeMillis()).apply();if(System.currentTimeMillis()-p.getLong("probe_start",0)>=86400000L){p.edit().putBoolean("probe_on",false).putLong("probe_end",System.currentTimeMillis()).apply();PowerDetail.stop();active=false;detach();}}
 private static synchronized void battery(int level,int plug){if(app==null)return;PowerDetail.count("battery_event");sample();SharedPreferences p=LedgerDb.prefs(app);if(p.getBoolean("probe_on",false)){
  SharedPreferences.Editor e=p.edit();if(lastLevel>=0&&level>=0&&lastPlug==0&&plug==0){e.putInt("probe_drop",p.getInt("probe_drop",0)+Math.max(0,lastLevel-level));}
  if(plug!=0)e.putBoolean("probe_charged",true);e.putInt("probe_level",level).apply();
 }lastLevel=level;lastPlug=plug;}
 public static synchronized void start(Context c){app=c.getApplicationContext();Intent b=app.registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));if(b!=null){int scale=b.getIntExtra("scale",100),level=b.getIntExtra("level",-1);lastLevel=scale>0&&level>=0?level*100/scale:-1;lastPlug=b.getIntExtra("plugged",0);}lastCpu=android.os.Process.getElapsedCpuTime();lastElapsed=SystemClock.elapsedRealtime();notifications.set(0);screens.set(0);LedgerDb.prefs(c).edit().putBoolean("probe_on",true).putLong("probe_start",System.currentTimeMillis()).putLong("probe_end",0).putLong("probe_cpu",0).putLong("probe_observed",0).putLong("probe_notifications",0).putLong("probe_screens",0).putInt("probe_start_level",lastLevel).putInt("probe_level",lastLevel).putInt("probe_drop",0).putBoolean("probe_charged",lastPlug>0).apply();PowerDetail.reset();active=true;attach();}
 public static void stop(Context c){sample();LedgerDb.prefs(c).edit().putBoolean("probe_on",false).putLong("probe_end",System.currentTimeMillis()).apply();PowerDetail.stop();active=false;detach();}
 public static JSONObject state(Context c)throws Exception{sample();SharedPreferences p=LedgerDb.prefs(c);JSONObject o=new JSONObject();for(String k:new String[]{"start","end","cpu","observed","notifications","screens","sample"})o.put(k,p.getLong("probe_"+k,0));o.put("running",p.getBoolean("probe_on",false));o.put("startLevel",p.getInt("probe_start_level",-1));o.put("level",lastLevel>=0?lastLevel:p.getInt("probe_level",-1));o.put("drop",p.getInt("probe_drop",0));o.put("charged",p.getBoolean("probe_charged",false));o.put("detail",PowerDetail.state());return o;}
}
